{"file_path":"src/uri-parser.js","content":"/**
 * Parse a URI reference into its components according to RFC 3986
 */

export class UriParser {
  static parse(uriRef) {
    let scheme = undefined
    let authority = undefined
    let path = ''
    let query = undefined
    let fragment = undefined

    let remaining = uriRef
    let pos = 0

    // Parse scheme: optional, runs to first `:` which may not be preceded by `/`, `?` or `#`
    const schemeMatch = remaining.match(/^([a-zA-Z][a-zA-Z0-9+\-.]*):/)
    if (schemeMatch) {
      scheme = schemeMatch[1]
      remaining = remaining.substring(schemeMatch[0].length)
    }

    // Parse authority: optional, introduced by `//`, runs to next `/`, `?` or `#`
    if (remaining.startsWith('//')) {
      remaining = remaining.substring(2)
      const authorityEndMatch = remaining.match(/[/?#]/)
      if (authorityEndMatch) {
        authority = remaining.substring(0, authorityEndMatch.index)
        remaining = remaining.substring(authorityEndMatch.index)
      } else {
        authority = remaining
        remaining = ''
      }
    }

    // Parse path: up to next `?` or `#`
    const pathEndMatch = remaining.match(/[?#]/)
    if (pathEndMatch) {
      path = remaining.substring(0, pathEndMatch.index)
      remaining = remaining.substring(pathEndMatch.index)
    } else {
      path = remaining
      remaining = ''
    }

    // Parse query: optional, from `?` to next `#`
    if (remaining.startsWith('?')) {
      remaining = remaining.substring(1)
      const queryEndMatch = remaining.match(/#/)
      if (queryEndMatch) {
        query = remaining.substring(0, queryEndMatch.index)
        remaining = remaining.substring(queryEndMatch.index)
      } else {
        query = remaining
        remaining = ''
      }
    }

    // Parse fragment: optional, from `#` to end
    if (remaining.startsWith('#')) {
      fragment = remaining.substring(1)
    }

    return {
      scheme,
      authority,
      path,
      query,
      fragment
    }
  }

  static parseAuthority(authority) {
    if (!authority) {
      return { userinfo: undefined, host: undefined, port: undefined }
    }

    let userinfo = undefined
    let host = ''
    let port = undefined

    // userinfo is everything before the last `@`
    const lastAtIndex = authority.lastIndexOf('@')
    if (lastAtIndex !== -1) {
      userinfo = authority.substring(0, lastAtIndex)
      authority = authority.substring(lastAtIndex + 1)
    }

    // port is everything after the first `:` that follows the last `]`
    const lastBracketIndex = authority.lastIndexOf(']')
    const colonIndex = authority.indexOf(':')

    if (colonIndex !== -1 && (lastBracketIndex === -1 || colonIndex > lastBracketIndex)) {
      host = authority.substring(0, colonIndex)
      port = authority.substring(colonIndex + 1)
    } else {
      host = authority
    }

    return { userinfo, host, port }
  }
}
"}

