{"file_path":"src/uri-normalizer.js","content":"/**
 * Normalize a URI according to RFC 3986
 */

import { UriParser } from './uri-parser.js'

export class UriNormalizer {
  static normalize(uri) {
    const normalized = { ...uri }

    // 1. Lowercase the scheme
    if (normalized.scheme) {
      normalized.scheme = normalized.scheme.toLowerCase()
    }

    // 2. Normalize percent-encodings and process authority
    if (normalized.authority) {
      const auth = UriParser.parseAuthority(normalized.authority)

      // Normalize userinfo
      if (auth.userinfo) {
        auth.userinfo = this.normalizePercentEncoding(auth.userinfo, 'userinfo')
      }

      // Normalize host
      if (auth.host) {
        auth.host = this.normalizePercentEncoding(auth.host, 'host')
        auth.host = auth.host.toLowerCase()
      }

      // Normalize port
      if (auth.port !== undefined) {
        auth.port = this.normalizePercentEncoding(auth.port, 'query')
        // Drop port if empty or default
        const defaultPorts = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }
        if (auth.port === '' || auth.port === defaultPorts[normalized.scheme]) {
          auth.port = undefined
        }
      }

      // Reconstruct authority
      normalized.authority = this.reconstructAuthority(auth)
    }

    // 3. Normalize path
    if (normalized.path !== undefined) {
      normalized.path = this.normalizePercentEncoding(normalized.path, 'path')
      // Remove dot segments
      normalized.path = this.removeDotSegments(normalized.path)
    }

