{"file_path":"cell-K38nO8/src/uri-parser.js","content":"/**
 * Parsing of URI references into their generic-syntax components, and of an
 * authority into userinfo, host and port. An absent component is `undefined`;
 * an empty one is the empty string.
 */

/**
 * Split a URI reference into scheme, authority, path, query and fragment.
 */
export function parseUri(uriRef) {
  let rest = uriRef
  let scheme

  // The scheme runs to the first ':' when no '/', '?' or '#' precedes it.
  const colon = rest.indexOf(':')
  if (colon !== -1) {
    const head = rest.slice(0, colon)
    if (!/[/?#]/.test(head)) {
      scheme = head
      rest = rest.slice(colon + 1)
    }
  }

  let authority
  if (rest.startsWith('//')) {
    rest = rest.slice(2)
    const end = rest.search(/[/?#]/)
    if (end === -1) {
      authority = rest
      rest = ''
    } else {
      authority = rest.slice(0, end)
      rest = rest.slice(end)
    }
  }

  let path
  const pathEnd = rest.search(/[?#]/)
  if (pathEnd === -1) {
    path = rest
    rest = ''
  } else {
    path = rest.slice(0, pathEnd)
    rest = rest.slice(pathEnd)
  }

  let query
  if (rest.startsWith('?')) {
    rest = rest.slice(1)
    const hash = rest.indexOf('#')
    if (hash === -1) {
      query = rest
      rest = ''
    } else {
      query = rest.slice(0, hash)
      rest = rest.slice(hash)
    }
  }

  let fragment
  if (rest.startsWith('#')) {
    fragment = rest.slice(1)
  }

  return { scheme, authority, path, query, fragment }
}

/**
 * Split an authority into userinfo, host and port. The userinfo is everything
 * before the last '@'; the port is everything after the first ':' that follows
 * the last ']'; the host is what lies between.
 */
export function parseAuthority(authority) {
  let rest = authority
  let userinfo

  const at = rest.lastIndexOf('@')
  if (at !== -1) {
    userinfo = rest.slice(0, at)
    rest = rest.slice(at + 1)
  }

  const bracket = rest.lastIndexOf(']')
  const colon = rest.indexOf(':', bracket + 1)

  let host = rest
  let port
  if (colon !== -1) {
    host = rest.slice(0, colon)
    port = rest.slice(colon + 1)
  }

  return { userinfo, host, port }
}

/**
 * Put an authority back together from its parts.
 */
export function formatAuthority({ userinfo, host, port }) {
  let out = ''
  if (userinfo !== undefined) out += userinfo + '@'
  out += host
  if (port !== undefined) out += ':' + port
  return out
}

/**
 * Put a URI back together from its components.
 */
export function formatUri({ scheme, authority, path, query, fragment }) {
  let out = ''
  if (scheme !== undefined) out += scheme + ':'
  if (authority !== undefined) out += '//' + authority
  out += path
  if (query !== undefined) out += '?' + query
  if (fragment !== undefined) out += '#' + fragment
  return out
}
