 * Resolution of a reference against a base, following RFC 3986 section 5.2.2
 * in its strict form.
 */

import { removeDotSegments } from './uri-normalizer.js'

/**
 * Merge a relative reference path onto the base path (RFC 3986 section 5.2.3).
 */
function merge(base, refPath) {
  if (base.authority !== undefined && base.path === '') return '/' + refPath
  const slash = base.path.lastIndexOf('/')
  if (slash === -1) return refPath
  return base.path.slice(0, slash + 1) + refPath
}

/**
 * Resolve `reference` against `base` and return the parsed target.
 */
export function resolve(base, reference) {
  if (reference.scheme !== undefined) {
    return {
      scheme: reference.scheme,
      authority: reference.authority,
      path: removeDotSegments(reference.path),
      query: reference.query,
      fragment: reference.fragment
    }
  }

  if (reference.authority !== undefined) {
    return {
      scheme: base.scheme,
      authority: reference.authority,
      path: removeDotSegments(reference.path),
      query: reference.query,
      fragment: reference.fragment
    }
  }

  if (reference.path === '') {
    return {
      scheme: base.scheme,
      authority: base.authority,
      path: base.path,
      query: reference.query === undefined ? base.query : reference.query,
      fragment: reference.fragment
    }
  }

  const path = reference.path.startsWith('/')
    ? removeDotSegments(reference.path)
    : removeDotSegments(merge(base, reference.path))

  return {
    scheme: base.scheme,
    authority: base.authority,
    path,
    query: reference.query,
    fragment: reference.fragment
  }
}
"}

