/**
 * Resolve a URI reference against a base URI according to RFC 3986 section 5.2.2
 */

export class UriResolver {
  static resolve(base, reference) {
    // RFC 3986 section 5.2.2 strict form

    let targetScheme
    let targetAuthority
    let targetPath
    let targetQuery
    let targetFragment

    // If reference has a scheme, it's the target
    if (reference.scheme !== undefined) {
      targetScheme = reference.scheme
      targetAuthority = reference.authority
      targetPath = this.removeDotSegments(reference.path)
      targetQuery = reference.query
    } else {
      // Reference doesn't have a scheme, use base scheme
      targetScheme = base.scheme

      if (reference.authority !== undefined) {
        // Reference has authority, use it
        targetAuthority = reference.authority
        targetPath = this.removeDotSegments(reference.path)
        targetQuery = reference.query
      } else {
        // Reference doesn't have authority, use base authority
        targetAuthority = base.authority

        if (reference.path === '') {
          // Reference has empty path
          targetPath = base.path

          if (reference.query !== undefined) {
            targetQuery = reference.query
          } else {
            targetQuery = base.query
          }
        } else {
          // Reference has non-empty path
          if (reference.path.startsWith('/')) {
            // Absolute path
            targetPath = this.removeDotSegments(reference.path)
          } else {
            // Relative path, merge with base
            targetPath = this.mergePaths(base, reference.path)
            targetPath = this.removeDotSegments(targetPath)
          }

          targetQuery = reference.query
        }
      }
    }

    targetFragment = reference.fragment

    return {
      scheme: targetScheme,
      authority: targetAuthority,
      path: targetPath,
      query: targetQuery,
      fragment: targetFragment
    }
  }

  static mergePaths(base, referencePath) {
    // RFC 3986 section 5.2.3
    if (base.authority !== undefined && base.path === '') {
      // Base has authority and empty path, contribute single leading `/`
      return '/' + referencePath
    } else {
      // Keep everything of base path up to and including its last `/`
      const lastSlashIndex = base.path.lastIndexOf('/')
      if (lastSlashIndex === -1) {
        return referencePath
      } else {
        return base.path.substring(0, lastSlashIndex + 1) + referencePath
      }
    }
  }

  static removeDotSegments(path) {
    // RFC 3986 section 5.2.4
    const inputBuffer = path.split('/')
    const outputBuffer = []

    for (let i = 0; i < inputBuffer.length; i++) {
      const segment = inputBuffer[i]

      if (segment === '.') {
        // Remove . segment
        continue
      } else if (segment === '..' && outputBuffer.length > 0 && outputBuffer[outputBuffer.length - 1] !== '') {
        // Remove .. and the preceding segment (but not the root)
        outputBuffer.pop()
      } else if (segment === '..') {
        // .. at root, discard
        continue
      } else {
        // Keep segment
        outputBuffer.push(segment)
      }
    }

    return outputBuffer.join('/')
  }
}

