import { createInterface } from 'readline'
import { stdin as stdinStream, stdout as stdoutStream, stderr as stderrStream } from 'process'
import { UriParser } from './uri-parser.js'
import { UriNormalizer } from './uri-normalizer.js'
import { UriResolver } from './uri-resolver.js'

const mode = process.argv[2]

// Validate mode
if (mode !== 'normalize' && mode !== 'resolve') {
  stderrStream.write('error: usage: cli.js normalize|resolve\n')
  process.exit(2)
}

const readline = createInterface({
  input: stdinStream,
  output: undefined,
  terminal: false
})

let lineNumber = 0
let hasError = false

readline.on('line', (line) => {
  lineNumber++

  if (hasError) {
    return
  }

  try {
    if (mode === 'normalize') {
      const parsed = UriParser.parse(line)
      const normalized = UriNormalizer.normalize(parsed)
      stdoutStream.write(normalized + '\n')
    } else if (mode === 'resolve') {
      const spaceIndex = line.indexOf(' ')
      if (spaceIndex === -1) {
        stderrStream.write(`error: line ${lineNumber}: expected a base and a reference\n`)
        hasError = true
        return
      }

      const basePart = line.substring(0, spaceIndex)
      const referencePart = line.substring(spaceIndex + 1)

      const baseParsed = UriParser.parse(basePart)
      if (!baseParsed.scheme) {
        stderrStream.write(`error: line ${lineNumber}: the base has no scheme\n`)
        hasError = true
        return
      }

      const refParsed = UriParser.parse(referencePart)
      const resolved = UriResolver.resolve(baseParsed, refParsed)
      const normalized = UriNormalizer.normalize(resolved)
      stdoutStream.write(normalized + '\n')
    }
  } catch (err) {
    stderrStream.write(`error: line ${lineNumber}: ${err.message}\n`)
    hasError = true
  }
})

readline.on('close', () => {
  if (hasError) {
    process.exit(2)
  } else {
    process.exit(0)
  }
})

readline.on('error', (err) => {
  stderrStream.write(`error: ${err.message}\n`)
  process.exit(2)
})

